import sqlite3
import json

conn = sqlite3.connect('db/users.db')
users = {row[0]: {'UpVotes': row[1], 'Age': row[2]} for row in conn.execute('SELECT Id, UpVotes, Age FROM users')}
conn.close()

with open('json/posts.json', 'r') as f:
    data = json.load(f)

post_counts = {}
for record in data['records']:
    owner = record.get('OwnerUserId')
    if owner is not None:
        post_counts[owner] = post_counts.get(owner, 0) + 1

user_data = []
for uid, counts in post_counts.items():
    if counts > 10 and uid in users:
        upvotes = users[uid]['UpVotes']
        age = users[uid]['Age']
        if upvotes is not None and age is not None:
            user_data.append((uid, upvotes, age, counts))

if user_data:
    avg_upvotes = sum(u[1] for u in user_data) / len(user_data)
    avg_age = sum(u[2] for u in user_data) / len(user_data)
    print(f'Users with >10 posts: {len(user_data)}')
    print(f'Average UpVotes: {avg_upvotes}')
    print(f'Average Age: {avg_age}')
else:
    print('No users found with >10 posts')

